// Simplified chartConfig.js with minimalist approach

export const getChartConfig = (darkMode) => {
  const colors = darkMode ? {
    text: '#D1D4DC',
    grid: '#2A2E39'
  } : {
    text: '#374151',
    grid: '#e5e7eb'
  };

  return {
    // Simpler margins with adequate space
    margin: { top: 10, right: 30, left: 20, bottom: 20 },

    // Simple formatter for numbers
    formatValue: (value) => {
      if (value >= 1000000) {
        return `${(value / 1000000).toFixed(1)}M`;
      } else if (value >= 1000) {
        return `${(value / 1000).toFixed(0)}K`;
      }
      return value.toString();
    },

    // Default styles for both charts
    defaultStyles: {
      // Chart background
      chartBackground: darkMode ? '#0D1015' : '#FFFFFF',

      // Text colors
      labelColor: colors.text,

      // Grid settings
      gridStroke: colors.grid,
      gridStrokeDasharray: '3 3',

      // Tooltip styles
      tooltipBackground: darkMode ? '#141418' : '#FFFFFF',
      tooltipBorder: darkMode ? '#2A2E39' : '#E5E7EB',

      // Legend styles
      legendWrapperStyle: { paddingTop: 10 }
    }
  };
};
